(function(){
  var $=function(id){return document.getElementById(id)};
  var num=function(n,d){return n.toLocaleString(undefined,{maximumFractionDigits:d===undefined?2:d})};
  function calc(){
    var aRaw=$('a').value, bRaw=$('b').value;
    if(aRaw===''||bRaw===''){ $('out').textContent='Enter two numbers'; $('work').textContent=''; return; }
    var a=+aRaw, b=+bRaw;
    if(!isFinite(a)||!isFinite(b)){ $('out').textContent='Both values must be numbers'; return; }
    var diff=b-a;
    if(a===0){
      // Percentage change from zero is undefined, not infinite. Say so rather
      // than printing Infinity, which is the usual bug in these calculators.
      $('out').textContent='Percentage change from 0 is undefined';
      $('pct').textContent='n/a'; $('plabel').textContent='Change';
      $('diff').textContent=num(diff); $('times').textContent='n/a';
      $('work').textContent='Going up from zero has no meaningful percentage, because there is nothing to compare against. The difference is '+num(diff)+'.';
      if(window.WT) WT.resize(); return;
    }
    // Divide by the magnitude so a change from -50 to -25 reads as a rise.
    var pct=diff/Math.abs(a)*100;
    var up=pct>0, flat=Math.abs(pct)<1e-12;
    $('pct').textContent=(up?'+':'')+num(pct)+'%';
    $('plabel').textContent = flat?'No change':(up?'Increase':'Decrease');
    $('diff').textContent=(up?'+':'')+num(diff);
    $('times').textContent=a!==0?num(b/a,3)+'x':'n/a';
    $('out').innerHTML='<span class="'+(flat?'':(up?'ic-up':'ic-down'))+'">'+
      num(a)+' to '+num(b)+' is '+(flat?'no change':(up?'an increase':'a decrease')+' of '+num(Math.abs(pct))+'%')+'</span>';
    $('work').textContent='('+num(b)+' minus '+num(a)+') divided by '+num(Math.abs(a))+
      ', times 100 = '+num(pct)+'%';
    if(window.WT) WT.resize();
  }
  ['a','b'].forEach(function(id){$(id).addEventListener('input',calc)});
  $('swap').addEventListener('click',function(){
    var t=$('a').value; $('a').value=$('b').value; $('b').value=t; calc();
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('out').textContent);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy result'},1400);
  });
  calc();
})();
